import json
import httpx
from fastmcp import FastMCP


def create_openapi_mcp_server(spec: dict, client: httpx.AsyncClient) -> FastMCP:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 specification as a dict
        client: httpx.AsyncClient configured with base URL

    Returns:
        FastMCP server instance with tools for each operation
    """
    mcp = FastMCP("openapi")

    http_methods = {"get", "post", "put", "patch", "delete", "head", "options"}

    for path, path_item in spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method.lower() not in http_methods:
                continue

            op_id = operation.get("operationId", f"{method}_{path}".replace("/", "_"))
            summary = operation.get("summary", f"{method.upper()} {path}")
            description = operation.get("description", "")
            params = operation.get("parameters", [])
            req_body = operation.get("requestBody")

            tool_desc = f"{summary}\n{description}" if description else summary

            # Build input schema
            props = {}
            required = []

            for p in params:
                name = p.get("name")
                props[name] = p.get("schema", {})
                if p.get("required"):
                    required.append(name)

            if req_body:
                body_schema = (
                    req_body.get("content", {})
                    .get("application/json", {})
                    .get("schema", {})
                )
                if body_schema:
                    props["body"] = body_schema
                    if req_body.get("required"):
                        required.append("body")

            input_schema = {
                "type": "object",
                "properties": props,
                "required": required
            }

            # Closure to capture method, path, params
            def mk_handler(m, p, params):
                async def tool_handler(**kwargs) -> str:
                    url = p
                    query_params = {}
                    json_body = None

                    for param in params:
                        pname = param.get("name")
                        if pname in kwargs:
                            val = kwargs[pname]
                            if param.get("in") == "path":
                                url = url.replace(f"{{{pname}}}", str(val))
                            else:
                                query_params[pname] = val

                    if "body" in kwargs:
                        json_body = kwargs["body"]

                    try:
                        resp = await client.request(
                            m.upper(), url,
                            params=query_params or None,
                            json=json_body
                        )
                        is_json = "application/json" in resp.headers.get("content-type", "")
                        return json.dumps({
                            "status": resp.status_code,
                            "body": resp.json() if is_json else resp.text
                        })
                    except Exception as e:
                        return json.dumps({"error": str(e)})

                return tool_handler

            handler = mk_handler(method, path, params)
            mcp.tool(name=op_id, description=tool_desc, input_schema=input_schema)(handler)

    return mcp


